declare
  c jsonb := '{"brand":"Aset Life","whatsapp":"5583920054465","categories":[{"name":"Emagrecimento & Metabolismo","slug":"emagrecimento-metabolismo","sort_order":1},{"name":"Pele, Colágeno & Estética","slug":"pele-colageno-estetica","sort_order":2},{"name":"Cognição & Neuro","slug":"cognicao-neuro","sort_order":3},{"name":"Energia Celular & Mitocôndrias","slug":"energia-celular-mitocondrias","sort_order":4},{"name":"Sono & Recuperação","slug":"sono-recuperacao","sort_order":5},{"name":"Soluções & Diluentes","slug":"solucoes-diluentes","sort_order":6},{"name":"Reparação & Recuperação","slug":"reparacao-recuperacao","sort_order":7},{"name":"Secretagogos de GH & Hormônios","slug":"secretagogos-de-gh-hormonios","sort_order":8}],"products":[{"id":"retatrutida","active":true,"name":"Retatrutida","category":"Emagrecimento & Metabolismo","shortDescription":"Peptídeo com ação sobre os receptores GLP-1, GIP e glucagon, estudado em pesquisas sobre metabolismo e controle do peso.","description":"A Retatrutida é um peptídeo agonista de múltiplos receptores hormonais, incluindo GLP-1, GIP e glucagon. É investigada em estudos sobre regulação do apetite, metabolismo energético, glicemia e composição corporal.","uses":"Pesquisa sobre metabolismo, regulação do apetite, glicemia e composição corporal.","evidence":"Possui estudos clínicos em andamento e resultados de pesquisa sobre redução de peso e parâmetros metabólicos. Não deve ser confundida com medicamentos já aprovados para outras indicações.","disclaimer":"Produto investigacional. Não representa medicamento aprovado para uso geral. Não utilizar sem avaliação profissional. Verificar procedência, identidade, documentação, esterilidade e situação regulatória.","variants":[{"size":"10 mg","price":350},{"size":"20 mg","price":650},{"size":"40 mg","price":1200}]},{"id":"tirzepatida","active":true,"name":"Tirzepatida","category":"Emagrecimento & Metabolismo","shortDescription":"Peptídeo com ação sobre os receptores GIP e GLP-1, relacionado à regulação metabólica e ao controle glicêmico.","description":"A Tirzepatida é um agonista dos receptores GIP e GLP-1, investigado e utilizado em contextos médicos específicos relacionados ao metabolismo da glicose e ao controle do peso. Sua atuação envolve mecanismos hormonais relacionados ao apetite, à secreção de insulina e ao metabolismo energético.","uses":"Pesquisa e aplicações clínicas regulamentadas relacionadas ao metabolismo da glicose e controle do peso, conforme indicação e bula aplicáveis.","evidence":"Possui evidência clínica robusta para indicações específicas e aprovações regulatórias em diferentes países. A utilização depende da apresentação, procedência e indicação autorizada.","disclaimer":"Medicamento de ação hormonal que exige avaliação e acompanhamento médico. As indicações e aprovações variam conforme o país. Não utilizar sem prescrição e sem verificar a regularidade do produto.","variants":[{"size":"10 mg","price":250},{"size":"20 mg","price":400},{"size":"40 mg","price":580},{"size":"60 mg","price":800}]},{"id":"ghk-cu","active":true,"name":"GHK-Cu","category":"Pele, Colágeno & Estética","shortDescription":"Peptídeo ligado ao cobre, investigado em pesquisas sobre colágeno, matriz extracelular, regeneração cutânea e sinalização celular.","description":"O GHK-Cu é um complexo formado pelo tripeptídeo glicil-histidil-lisina ligado ao cobre. É estudado por sua participação em mecanismos relacionados ao metabolismo do colágeno, remodelação da matriz extracelular, integridade da pele e sinalização celular.","uses":"Pesquisa sobre colágeno, matriz extracelular, biologia da pele e remodelação tecidual.","evidence":"Possui estudos laboratoriais e pré-clínicos sobre mecanismos relacionados à pele e à matriz extracelular. Os resultados não comprovam eficácia clínica de todas as apresentações comerciais.","disclaimer":"Conteúdo informativo. Verificar identidade, concentração, procedência, documentação analítica, esterilidade e situação regulatória.","variants":[{"size":"50 mg","price":300},{"size":"100 mg","price":500}]},{"id":"selank","active":true,"name":"Selank","category":"Cognição & Neuro","shortDescription":"Peptídeo sintético investigado em pesquisas sobre neurotransmissão, resposta ao estresse e regulação neurobiológica.","description":"O Selank é um peptídeo sintético investigado por sua possível influência em mecanismos de neurotransmissão, sinalização neuronal e resposta fisiológica ao estresse. É objeto de pesquisas sobre processos neurobiológicos e comportamento.","uses":"Pesquisa experimental sobre neurotransmissão, sinalização neuronal e resposta ao estresse.","evidence":"A evidência disponível é limitada e inclui pesquisas pré-clínicas e estudos clínicos de escopo restrito. Não estabelece eficácia ampla para alterações cognitivas ou transtornos de ansiedade.","disclaimer":"Produto de investigação. Não representa tratamento comprovado para ansiedade ou outras condições neurológicas. Verificar procedência, identidade, documentação e situação regulatória.","variants":[{"size":"5 mg","price":300},{"size":"10 mg","price":500}]},{"id":"ahk-cu","active":true,"name":"AHK-Cu","category":"Pele, Colágeno & Estética","shortDescription":"Peptídeo ligado ao cobre investigado em pesquisas sobre biologia da pele, folículos capilares e sinalização celular.","description":"O AHK-Cu é um peptídeo ligado ao cobre estudado em modelos experimentais relacionados à atividade dos folículos capilares, biologia da pele e mecanismos de sinalização celular. Seu interesse científico envolve processos de manutenção e remodelação dos tecidos.","uses":"Pesquisa experimental sobre folículos capilares, pele e sinalização celular.","evidence":"A literatura disponível é predominantemente experimental. Não comprova eficácia clínica para crescimento capilar ou tratamento de alterações dermatológicas.","disclaimer":"Conteúdo informativo. Não representa tratamento capilar ou dermatológico comprovado. Verificar identidade, procedência, documentação e situação regulatória.","variants":[{"size":"50 mg","price":350},{"size":"100 mg","price":600}]},{"id":"melanotan-2","active":true,"name":"Melanotan 2","category":"Pele, Colágeno & Estética","shortDescription":"Peptídeo sintético melanocortínico investigado em pesquisas sobre pigmentação e receptores melanocortínicos.","description":"O Melanotan 2 é um peptídeo sintético relacionado ao sistema melanocortínico. É estudado por sua interação com receptores melanocortínicos envolvidos em processos fisiológicos como pigmentação e outras funções biológicas.","uses":"Pesquisa sobre receptores melanocortínicos, pigmentação e sinalização celular.","evidence":"Existem estudos farmacológicos sobre a atividade melanocortínica, mas não há base para considerar todas as aplicações comerciais seguras ou clinicamente comprovadas.","disclaimer":"Produto investigacional. Não é substituto de proteção solar e não deve ser considerado método seguro de bronzeamento. Verificar procedência e situação regulatória.","variants":[{"size":"10 mg","price":460}]},{"id":"ss-31","active":true,"name":"SS-31","category":"Energia Celular & Mitocôndrias","shortDescription":"Peptídeo direcionado às mitocôndrias, investigado em pesquisas sobre função mitocondrial e estresse oxidativo.","description":"O SS-31, também conhecido como elamipretida, é um peptídeo estudado por sua interação com componentes da membrana mitocondrial. As pesquisas exploram sua relação com a organização mitocondrial, eficiência bioenergética e mecanismos de estresse oxidativo.","uses":"Pesquisa sobre função mitocondrial, bioenergética celular e estresse oxidativo.","evidence":"Possui estudos pré-clínicos e clínicos em condições específicas. Os resultados não estabelecem benefícios gerais para longevidade, energia ou desempenho físico.","disclaimer":"Molécula investigacional, com situação regulatória variável conforme o país e a indicação. Não representa tratamento geral para disfunção mitocondrial ou envelhecimento.","variants":[{"size":"10 mg","price":600}]},{"id":"dsip","active":true,"name":"DSIP","category":"Sono & Recuperação","shortDescription":"Peptídeo investigado em pesquisas sobre sono, sinalização neuroendócrina e regulação fisiológica.","description":"O DSIP (Delta Sleep-Inducing Peptide) é um peptídeo estudado em pesquisas sobre mecanismos relacionados ao sono, atividade neuroendócrina e regulação de processos fisiológicos. Seu papel biológico ainda é objeto de investigação.","uses":"Pesquisa experimental sobre sono, sinalização neuroendócrina e regulação fisiológica.","evidence":"Os estudos disponíveis são limitados e não estabelecem eficácia clínica consistente para tratamento de insônia ou outros distúrbios do sono.","disclaimer":"Produto investigacional. Não deve ser considerado tratamento comprovado para distúrbios do sono. Verificar procedência, identidade e situação regulatória.","variants":[{"size":"5 mg","price":400},{"size":"10 mg","price":700}]},{"id":"semax","active":true,"name":"Semax","category":"Cognição & Neuro","shortDescription":"Peptídeo sintético derivado de fragmento de ACTH, investigado em pesquisas sobre sinalização neuronal e neuroproteção.","description":"O Semax é um peptídeo sintético derivado de um fragmento do hormônio adrenocorticotrófico (ACTH). É estudado em pesquisas sobre sinalização neuronal, fatores neurotróficos, neuroproteção e processos relacionados à função cognitiva.","uses":"Pesquisa experimental sobre neurobiologia, sinalização neuronal e mecanismos de neuroproteção.","evidence":"Existem estudos realizados principalmente em determinados contextos de pesquisa, mas a evidência não comprova eficácia ampla para melhora cognitiva ou tratamento de doenças neurológicas.","disclaimer":"Produto investigacional. Não representa tratamento comprovado para alterações cognitivas ou neurológicas. Verificar procedência e situação regulatória.","variants":[{"size":"5 mg","price":300},{"size":"10 mg","price":500}]},{"id":"epithalon","active":true,"name":"Epithalon","category":"Energia Celular & Mitocôndrias","shortDescription":"Peptídeo sintético investigado em pesquisas sobre envelhecimento celular, regulação biológica e atividade da telomerase.","description":"O Epithalon, também conhecido como Epitalon, é um tetrapeptídeo sintético investigado em pesquisas sobre processos de envelhecimento celular, regulação biológica e mecanismos relacionados à atividade da telomerase.","uses":"Pesquisa experimental sobre envelhecimento celular, sinalização biológica e mecanismos relacionados aos telômeros.","evidence":"A evidência disponível é limitada e não estabelece benefícios clínicos comprovados para longevidade ou prevenção do envelhecimento.","disclaimer":"Produto investigacional. Não deve ser apresentado como tratamento antienvelhecimento comprovado. Verificar procedência e situação regulatória.","variants":[{"size":"10 mg","price":580},{"size":"50 mg","price":920}]},{"id":"pt-141","active":true,"name":"PT-141","category":"Pele, Colágeno & Estética","shortDescription":"Peptídeo melanocortínico investigado em pesquisas sobre sinalização do sistema nervoso central e função sexual.","description":"O PT-141, também conhecido como bremelanotida, é um peptídeo sintético relacionado ao sistema melanocortínico. É investigado por sua atuação em receptores melanocortínicos e mecanismos de sinalização do sistema nervoso central relacionados à função sexual.","uses":"Pesquisa sobre receptores melanocortínicos e sinalização neurobiológica relacionada à função sexual.","evidence":"A bremelanotida possui aprovação nos Estados Unidos para uma indicação específica de transtorno do desejo sexual hipoativo adquirido e generalizado em mulheres na pré-menopausa. Essa aprovação não se estende automaticamente a outras populações ou apresentações.","disclaimer":"A situação regulatória e as indicações variam conforme o país. Não representa indicação geral para disfunção sexual. Verificar procedência, identidade e regularidade do produto.","variants":[{"size":"10 mg","price":380}]},{"id":"agua-bacteriostatica","active":true,"name":"Água Bacteriostática 0,9% (Álcool Benzílico)","category":"Soluções & Diluentes","shortDescription":"Solução aquosa com álcool benzílico, apresentada em frascos de 3 mL e 10 mL.","description":"Solução apresentada como água bacteriostática com álcool benzílico a 0,9%. A composição, finalidade, compatibilidade e condições de uso devem ser verificadas na documentação específica do fabricante.","uses":"Solução de interesse técnico, cuja compatibilidade depende da formulação e das especificações do fabricante.","evidence":"A adequação da solução depende da composição, qualidade microbiológica, processo de fabricação e documentação do lote.","disclaimer":"Não presumir esterilidade, compatibilidade universal ou adequação para uso humano. Verificar rótulo, documentação, procedência e situação regulatória.","variants":[{"size":"3 mL","price":30},{"size":"10 mL","price":70}]},{"id":"acetic-acid-water","active":true,"name":"Acetic Acid Water 0,6%","category":"Soluções & Diluentes","shortDescription":"Solução aquosa de ácido acético a 0,6%, apresentada em frasco de 3 mL.","description":"Solução aquosa de ácido acético a 0,6%. Sua composição e compatibilidade físico-química devem ser verificadas conforme as especificações do fabricante e as características de cada formulação.","uses":"Solução de interesse técnico para aplicações específicas documentadas pelo fabricante.","evidence":"A adequação depende da caracterização da solução, estabilidade, qualidade e compatibilidade com a substância considerada.","disclaimer":"Não presumir esterilidade ou adequação para uso humano. Não utilizar sem documentação que comprove finalidade, qualidade e compatibilidade.","variants":[{"size":"3 mL","price":50}]},{"id":"blend-bpc157-tb500-ghkcu-kpv","active":true,"name":"Blend BPC-157 + TB-500 + GHK-Cu + KPV","category":"Reparação & Recuperação","shortDescription":"Combinação de quatro peptídeos investigados em pesquisas sobre reparação tecidual, matriz extracelular, sinalização inflamatória e biologia da pele.","description":"Blend composto por BPC-157, TB-500, GHK-Cu e KPV. Reúne diferentes linhas de investigação relacionadas à reparação tecidual, migração celular, metabolismo do colágeno e modulação inflamatória.\n\nComposição por frasco: BPC-157 10 mg, TB-500 10 mg, GHK-Cu 50 mg e KPV 10 mg. Total de 80 mg por frasco. Embalagem com 10 frascos por caixa.","uses":"Pesquisa experimental sobre reparação tecidual, matriz extracelular, migração celular, inflamação e biologia cutânea.","evidence":"Os componentes possuem linhas de investigação individuais, principalmente pré-clínicas. Isso não comprova eficácia, segurança ou sinergia da combinação.","disclaimer":"Blend investigacional. Não representa tratamento comprovado. Verificar composição, identidade, documentação, esterilidade e situação regulatória.","variants":[{"size":"80 mg","price":900}]},{"id":"blend-bpc157-tb500-ghkcu","active":true,"name":"Blend BPC-157 + TB-500 + GHK-Cu","category":"Reparação & Recuperação","shortDescription":"Combinação de BPC-157, TB-500 e GHK-Cu, investigada em pesquisas sobre reparação tecidual, migração celular, colágeno e regeneração cutânea.","description":"Formulação combinada de BPC-157, TB-500 e GHK-Cu. Reúne moléculas investigadas em diferentes mecanismos relacionados à reparação tecidual, migração celular, angiogênese e metabolismo do colágeno.\n\nComposição por frasco: BPC-157 10 mg, TB-500 10 mg e GHK-Cu 50 mg. Total de 70 mg por frasco. Embalagem com 10 frascos por caixa.","uses":"Pesquisa experimental sobre reparação tecidual, estruturas musculoesqueléticas, matriz extracelular e biologia cutânea.","evidence":"Os componentes possuem evidências individuais predominantemente pré-clínicas. Não há comprovação de eficácia, segurança ou sinergia da combinação.","disclaimer":"Blend investigacional. Não representa tratamento comprovado. Verificar identidade, composição, documentação, esterilidade e situação regulatória.","variants":[{"size":"70 mg","price":800}]},{"id":"blend-bpc157-tb500","active":true,"name":"Blend BPC-157 + TB-500","category":"Reparação & Recuperação","shortDescription":"Combinação de BPC-157 e TB-500, investigada em pesquisas sobre reparação tecidual, migração celular e estruturas musculoesqueléticas.","description":"Formulação que combina BPC-157 e TB-500, dois peptídeos de interesse científico em pesquisas sobre integridade dos tecidos, migração celular, organização da actina e mecanismos de reparação.\n\nComposição por frasco: BPC-157 5 mg e TB-500 5 mg. Total de 10 mg por frasco. Embalagem com 10 frascos por caixa.","uses":"Pesquisa experimental sobre reparação tecidual, músculos, tendões, ligamentos e migração celular.","evidence":"A evidência dos componentes é predominantemente experimental. Não comprova eficácia ou segurança clínica da combinação.","disclaimer":"Blend investigacional. Não representa tratamento comprovado. Verificar identidade, composição, documentação, esterilidade e situação regulatória.","variants":[{"size":"10 mg","price":500}]},{"id":"ipamorelina","active":true,"name":"Ipamorelina","category":"Secretagogos de GH & Hormônios","shortDescription":"Pentapeptídeo sintético da classe dos secretagogos de GH, investigado pela ativação do receptor GHSR-1a.","description":"A Ipamorelina é um pentapeptídeo sintético pertencente à classe dos secretagogos do hormônio do crescimento. É investigada por sua interação com o receptor de grelina GHSR-1a e pela estimulação da secreção endógena de GH.\n\nEstudos farmacológicos exploram sua seletividade hormonal e sua relação com o eixo GH/IGF-1, metabolismo energético e manutenção dos tecidos.","uses":"Pesquisa sobre secreção de GH, receptor GHSR-1a, eixo GH/IGF-1 e regulação metabólica.","evidence":"Possui estudos farmacológicos e clínicos limitados. Não estabelece benefícios amplos para composição corporal, recuperação muscular ou envelhecimento.","disclaimer":"Molécula de ação hormonal. Não representa tratamento comprovado para alterações hormonais ou composição corporal. Verificar procedência, identidade e situação regulatória.","variants":[{"size":"5 mg","price":350},{"size":"10 mg","price":550}]},{"id":"kpv","active":true,"name":"KPV","category":"Reparação & Recuperação","shortDescription":"Tripeptídeo derivado da sequência terminal do α-MSH, investigado em pesquisas sobre modulação inflamatória e integridade intestinal e cutânea.","description":"O KPV é um tripeptídeo formado pelos aminoácidos lisina, prolina e valina, derivado da sequência terminal do hormônio α-MSH. É investigado por sua participação em mecanismos de sinalização celular relacionados à resposta inflamatória e à regulação imunológica.\n\nPesquisas experimentais exploram sua possível influência sobre vias NF-κB e MAPK, além de sua relação com o transportador de peptídeos PepT1 em modelos de inflamação intestinal.","uses":"Pesquisa experimental sobre sinalização inflamatória, vias NF-κB e MAPK, inflamação gastrointestinal e biologia cutânea.","evidence":"As pesquisas disponíveis são predominantemente pré-clínicas. Não comprovam eficácia clínica em seres humanos para doenças inflamatórias ou dermatológicas.","disclaimer":"Produto investigacional. Não representa tratamento comprovado para doenças inflamatórias, gastrointestinais ou dermatológicas. Verificar procedência e situação regulatória.","variants":[{"size":"10 mg","price":500}]},{"id":"tesamorelina","active":true,"name":"Tesamorelina","category":"Secretagogos de GH & Hormônios","shortDescription":"Peptídeo sintético análogo ao GHRH, investigado pela estimulação de GH e por seus efeitos sobre o eixo GH/IGF-1 e gordura visceral.","description":"A Tesamorelina é um peptídeo sintético análogo ao GHRH, desenvolvido para estimular a secreção endógena do hormônio do crescimento. Sua atuação está relacionada aos receptores de GHRH da hipófise e ao eixo GH/IGF-1.\n\nPossui interesse científico particular em pesquisas sobre gordura visceral, composição corporal e metabolismo lipídico.","uses":"Pesquisa sobre secreção de GH, eixo GH/IGF-1, gordura visceral e metabolismo energético.","evidence":"Possui estudos clínicos sobre gordura visceral em populações específicas. Nos Estados Unidos, possui aprovação para uma indicação restrita relacionada ao excesso de gordura abdominal em adultos com HIV e lipodistrofia. Isso não representa aprovação geral para emagrecimento.","disclaimer":"Peptídeo de ação hormonal. As indicações e aprovações variam conforme o país. Não representa tratamento geral para emagrecimento. Verificar procedência e situação regulatória.","variants":[{"size":"5 mg","price":350},{"size":"10 mg","price":600}]},{"id":"nad-plus","active":true,"name":"NAD+ (10 mL)","category":"Energia Celular & Mitocôndrias","shortDescription":"Coenzima essencial ao metabolismo energético, à função mitocondrial e aos mecanismos celulares de manutenção do DNA.","description":"O NAD+ (Nicotinamida Adenina Dinucleotídeo) é uma coenzima presente nas células e fundamental para diversas reações bioquímicas. Participa das reações de oxirredução NAD+/NADH, da produção de ATP e de processos relacionados à atividade das enzimas PARPs e sirtuínas.\n\nÉ amplamente investigado em pesquisas sobre metabolismo celular, função mitocondrial e envelhecimento biológico. Apresentação informada em frascos de 10 mL.","uses":"Pesquisa sobre metabolismo energético, função mitocondrial, equilíbrio NAD+/NADH, PARPs, sirtuínas e manutenção celular.","evidence":"O papel bioquímico do NAD+ é bem estabelecido. Entretanto, os benefícios clínicos de apresentações comerciais para energia, longevidade e desempenho dependem de estudos específicos sobre formulação e via de utilização.","disclaimer":"A importância fisiológica do NAD+ não comprova benefícios clínicos de uma apresentação específica. Verificar concentração, composição, procedência, documentação, esterilidade e situação regulatória.","variants":[{"size":"500 mg (10 mL)","price":480},{"size":"1000 mg (10 mL)","price":750}]},{"id":"mots-c","active":true,"name":"MOTS-C","category":"Energia Celular & Mitocôndrias","shortDescription":"Peptídeo mitocondrial de 16 aminoácidos, investigado em pesquisas sobre metabolismo energético, via AMPK e sensibilidade à insulina.","description":"O MOTS-C é um peptídeo mitocondrial composto por 16 aminoácidos, codificado pelo DNA mitocondrial. É estudado por sua participação na comunicação entre mitocôndrias e núcleo celular e por sua possível influência sobre mecanismos de regulação metabólica.\n\nO interesse científico está relacionado à via AMPK, à utilização de glicose, ao metabolismo de lipídios e à adaptação celular ao estresse metabólico.","uses":"Pesquisa experimental sobre comunicação mitocondrial, AMPK, sensibilidade à insulina, metabolismo da glicose e adaptação ao exercício.","evidence":"Possui estudos pré-clínicos sobre sinalização metabólica e função mitocondrial. Ainda não estabelece eficácia ou segurança clínica para controle de peso, desempenho físico ou tratamento de alterações metabólicas.","disclaimer":"Produto investigacional. Não representa tratamento comprovado para diabetes, obesidade, envelhecimento ou melhora do desempenho físico. Verificar procedência e situação regulatória.","variants":[{"size":"10 mg","price":500},{"size":"40 mg","price":1200}]}],"affiliates":[{"id":"BP1001","name":"Afiliado Exemplo 1","active":true},{"id":"BP1002","name":"Afiliado Exemplo 2","active":true}]}'::jsonb;
  p jsonb;
  v jsonb;
  a jsonb;
  cat jsonb;
  product_uuid uuid;
  category_uuid uuid;
  sort_idx integer;
  variant_idx integer;
  parsed_value numeric;
  parsed_unit text;
  variant_sku text;
begin
  insert into public.site_settings(key,value,is_public)
  values
    ('brand', to_jsonb(c->>'brand'), true),
    ('whatsapp', to_jsonb(c->>'whatsapp'), true)
  on conflict(key) do update set value=excluded.value, is_public=excluded.is_public;

  for cat in select value from jsonb_array_elements(c->'categories') loop
    insert into public.categories(name,slug,active,sort_order)
    values(cat->>'name',cat->>'slug',true,(cat->>'sort_order')::integer)
    on conflict(name) do update set slug=excluded.slug, active=true, sort_order=excluded.sort_order;
  end loop;

  sort_idx := 0;
  for p in select value from jsonb_array_elements(c->'products') loop
    sort_idx := sort_idx + 1;
    insert into public.products(legacy_id,name,slug,short_description,description,uses,evidence,disclaimer,active,sort_order)
    values(
      p->>'id',p->>'name',p->>'id',
      p->>'shortDescription',p->>'description',p->>'uses',p->>'evidence',p->>'disclaimer',
      coalesce((p->>'active')::boolean,true),sort_idx
    )
    on conflict(legacy_id) do update set
      name=excluded.name, slug=excluded.slug, short_description=excluded.short_description,
      description=excluded.description, uses=excluded.uses, evidence=excluded.evidence,
      disclaimer=excluded.disclaimer, active=excluded.active, sort_order=excluded.sort_order,
      updated_at=now()
    returning id into product_uuid;

    delete from public.product_categories where product_id=product_uuid;
    for cat in select value from jsonb_array_elements(c->'categories') where value->>'name'=p->>'category' loop
      select id into category_uuid from public.categories where name=cat->>'name';
      insert into public.product_categories(product_id,category_id)
      values(product_uuid,category_uuid) on conflict do nothing;
    end loop;

    variant_idx := 0;
    for v in select value from jsonb_array_elements(p->'variants') loop
      variant_idx := variant_idx + 1;
      parsed_value := null;
      parsed_unit := null;
      if (regexp_match(v->>'size','([0-9]+([.][0-9]+)?)\s*(mg|mL)')) is not null then
        parsed_value := (regexp_match(v->>'size','([0-9]+([.][0-9]+)?)\s*(mg|mL)'))[1]::numeric;
        parsed_unit := (regexp_match(v->>'size','([0-9]+([.][0-9]+)?)\s*(mg|mL)'))[3];
      end if;
      variant_sku := p->>'id' || '-' || lower(regexp_replace(v->>'size','[^a-zA-Z0-9]+','-','g'));
      insert into public.product_variants(product_id,legacy_variant_key,sku,name,quantity_value,quantity_unit,price,active,sort_order)
      values(product_uuid, p->>'id' || ':' || (v->>'size'), variant_sku, v->>'size',
        parsed_value, parsed_unit, (v->>'price')::numeric, true, variant_idx)
      on conflict(product_id,name) do update set
        legacy_variant_key=excluded.legacy_variant_key, sku=excluded.sku,
        quantity_value=excluded.quantity_value, quantity_unit=excluded.quantity_unit,
        price=excluded.price, active=true, sort_order=excluded.sort_order, updated_at=now();
    end loop;
  end loop;

  for a in select value from jsonb_array_elements(c->'affiliates') loop
    insert into public.affiliates(legacy_id,name,code,active)
    values(a->>'id',a->>'name',a->>'id',false)
    on conflict(legacy_id) do update set name=excluded.name,code=excluded.code,active=excluded.active,updated_at=now();
  end loop;
end
$seed$;
commit;
